import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val array = IntArray(n)
    for (i in 0 until n) {
        array[i] = scanner.nextInt()
    }
    array.sort()

    var sum = 4.5 * n

    for (i in 0 until n) {
        sum -= array[i]
    }

    if (sum <= 0) {
        println(0)
        return
    }

    sum = -sum
    var result = 0
    for (i in 0 until n) {
        sum += (5 - array[i])
        result++
        if (sum >= 0) {
            break
        }
    }
    println(result)
}

